package com.wansheng.visitor.guard;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/guard")class GuardInternalQueryController{private final GuardRepository repo;private final String token;GuardInternalQueryController(GuardRepository r,@Value("${visitor.guard.internal-token}")String t){repo=r;token=t;}private void check(String t){if(token.isBlank()||!token.equals(t))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}@GetMapping("/records")List<GuardRecord>records(@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return repo.listAll();}@GetMapping("/records/{id}/dormitory-view")ManualDormitoryView dormitoryView(@PathVariable String id,@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);GuardRecord r=repo.find(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return new ManualDormitoryView(r.visitId(),r.visitorName(),r.mobile(),r.hostName(),r.accommodationRequired(),r.plateNumber(),r.vehicleEnteringFactory());}@GetMapping("/audits")List<Map<String,Object>>audits(@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return repo.audits();}record ManualDormitoryView(String visitId,String visitorName,String mobile,String hostName,boolean accommodationRequired,String plateNumber,boolean vehicleEnteringFactory){}}
